<form class="filter panel" method="get"><label>Search food or city<input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Try rice, vegetables, Manipal..."></label><label>Food preference<select name="type"><option value="">All food types</option><?php foreach(['Vegetarian','Non-vegetarian','Vegan'] as $t):?><option <?=($_GET['type']??'')===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></label><button class="button">Find food</button><a href="<?=e(strtok($_SERVER['REQUEST_URI'],'?'))?>">Clear</a></form><?php $q='%'.trim($_GET['q']??'').'%';$type=$_GET['type']??'';cards(query("SELECT d.* FROM donations d JOIN users u ON u.id=d.donor_id WHERE d.status='pending' AND u.status='approved' AND (d.title LIKE ? OR d.city LIKE ?) AND (?='' OR d.food_type=?) ORDER BY d.deadline",[$q,$q,$type,$type])->fetchAll());?>